/* eslint no-new-func: "off" */
var strToJsonFunc = str => new Function("return ".concat(str))();
var strToJson = str => {
  try {
    return strToJsonFunc(str);
  } catch (e) {
    return str;
  }
};

/**
 * String To Json
 * @param str
 * @returns {string | JSON}
 */
export default (str => strToJson(strToJson(str)));